import json
from pathlib import Path
roots = [Path('products/services/catalogue-commission-terms'), Path('products/services/catalogue-inbound-cad')]
needed = {'terms-en-fr.md', 'acceptance-crosswalk.json', 'operator-reply-packet.json'}
for root in roots:
    files = sorted(path for path in root.rglob('*') if path.is_file())
    print(json.dumps({'directory': str(root), 'files': [str(path) for path in files]}))
    for path in files:
        if path.name in needed:
            print(json.dumps({'path': str(path), 'content': path.read_text(encoding='utf-8')}, ensure_ascii=False))
